          detail: "쉼표나 탭으로 나뉜 파일을 첨부 목록에서 눌러 여시면, 종전에는 줄번호가 붙은 원문이 그대로 나와 어디까지가 한 칸인지 회원님이 눈으로 맞추셔야 했습니다. 이제 첫 줄을 머리글로 삼은 격자로 그려 드립니다. 표를 아래로 내려도 머리글은 위에 붙어 있고, 숫자 칸은 오른쪽으로 맞춰 자릿수가 눈에 들어옵니다. 따옴표 안에 든 쉼표나 줄바꿈은 한 칸으로 묶여 값이 갈라지지 않습니다. 원문 그대로 보고 싶으시면 「표로 보기」 를 끄시면 됩니다 — 내용은 종전과 한 글자도 다르지 않고, 끄고 켜신 선택은 다음에 여실 때도 유지됩니다. 열이 아주 많거나 내용이 아주 길어 다 담지 못할 때는 잘랐다는 사실을 창 위에 알려 드리고, 따옴표 짝이 맞지 않는 칸이 있으면 그 개수도 함께 알려 드립니다. 버전 비교 창에서도 두 버전의 내용이 같을 때는 표로 보이고, 바뀐 줄이 있는 비교 화면에는 이 단추가 뜨지 않습니다 — 어느 줄이 바뀌었는지가 격자에서는 사라지기 때문입니다. 확인한 것: 실제 앱 창에서 격자가 그려지고 열이 눈금대로 갈리는 것, 표를 내려도 머리글이 남는 것, 「표로 보기」 를 끄면 원문으로 돌아오는 것을 재었습니다. 아직 확인하지 못한 것도 적습니다 — 그 확인은 미리 준비한 표본 파일로 한 것이고, 회원님 계정의 실제 첨부를 앱에서 열어 보는 것은 아직 재지 못했습니다.",
