          detail: "종전에는 두 버전을 글자 그대로만 맞춰 보아서, 들여쓰기가 밀렸거나 대소문자·띄어쓰기만 달라진 줄이 「지운 줄」 과 「새로 넣은 줄」 로 따로 떨어졌습니다. 감싸는 구문 하나를 넣어 전체가 한 칸씩 밀리면 파일 전체가 바뀐 것처럼 보여, 정작 무엇이 달라졌는지 찾기 어려웠습니다. 이제는 같은 짜임의 줄을 먼저 마주 놓고, 남은 자리에서는 문장이 얼마나 닮았는지를 보고 짝을 지어 「끼워 넣은 줄」 과 「고친 줄」 을 갈라 드립니다. 보기 좋게 맞춘 것일 뿐 원문은 그대로 남습니다 — 글자가 완전히 같을 때만 「같음」 으로 접히고, 따옴표 안의 글자나 대소문자가 달라진 것은 숨기지 않습니다. 아주 긴 파일이라 짝을 짓는 계산이 한도를 넘으면 그 부분은 종전 방식으로 낮추고, 그렇게 했다는 사실을 화면에 알려 드립니다. 이것은 두 SQL 의 뜻이 같은지 판단하는 기능이 아니라 줄의 생김새를 견주는 기능입니다. 아직 확인하지 못한 것: 설치하신 앱에서 회원님의 실제 첨부로 비교해 보는 확인은 남아 있습니다.",
