          detail: "회원님 요청은 「DQA클라이언트가 구성됨에 따라, 대화를 링크로 공유할 때 일반적인 웹브라우저로 해당 링크를 통해 내용을 확인할 수 있지만 대화에 참여하거나 fork 하려면 클라이언트를 통해 진행되도록 정합하게 구성해주세요」 였습니다. 열람은 손대지 않았습니다 — 링크를 받으신 분은 종전처럼 브라우저로 내용을 그대로 보시고, 로그인하지 않은 분도 종전과 같습니다. 바뀐 것은 그 아래 단추입니다. 브라우저에서는 앱으로 여는 단추 하나가 나오고, 앱 창 안에서 보고 계시면 그 자리에서 바로 참여·이어쓰기로 넘어갑니다. 앱이 없는 분께는 같은 자리에 받기 안내를 함께 냅니다 — 앱으로만 가라고 하면서 받을 곳을 알려 드리지 않으면 그 자리가 막다른 길이 되기 때문입니다. 그래서 앱 전용은 그 전제가 갖춰졌을 때만 적용합니다: 앱이 있을 수 없는 기기(윈도우가 아닌 기기)나 받을 곳이 없는 경우에는 종전 웹 경로가 그대로 보이고, 그 갈래에서 로그인하지 않은 분께는 로그인 진입을 남깁니다. 범위도 그대로 적습니다 — 이 갈래가 정하는 것은 「어느 화면에서 누르는가」 이고, 참여·이어쓰기를 할 수 있는지 없는지의 판정은 종전과 같습니다. 내보내기 전에 세 번에 걸쳐 스스로 헐뜯어 보는 검토를 했고, 매번 결함이 나왔습니다. 뒤로 갈수록 「직전 조치가 만든 되돌이」 였습니다 — 링크 한 줄로 회원님 브라우저에 저희 연결용 값을 몰래 심을 수 있던 것, 그리고 회원님이 9월 7일에 겪으신 「프로그램이 자기 자신을 열겠다고 묻던」 그 조건이 저희 조치 때문에 되살아나 있던 것입니다. 둘 다 내보내기 전에 잡아 되돌렸습니다. 배포한 뒤 확인한 것: 이번 변화가 실제로 서비스에서 돌고 있고, 새 화면 조각이 옛 사본이 아니라 새것으로 브라우저에 도달하는 것까지 봤습니다. 아직 확인하지 못한 것: 앱이 「그 대화」 를 여는 마지막 걸음은 설치본 쪽 변화라 새 앱 버전을 받으신 뒤에만 성립합니다. 지금 배포된 것은 서비스 쪽이라 종전 앱은 목적지를 몰라 서비스 첫 화면을 엽니다 — 파손이 아니라 의도한 내려앉음입니다. 화면에서 어느 단추가 보이는지도 아직 보지 못했습니다. 라이브에서 실제 공유 링크를 만들어 확인하는 일은 운영 자료에 잔재를 남기므로 하지 않았습니다.",
