          detail: "회원님 요청은 「이제 '연결 준비' 의 역할은 클라이언트가 모두 수행하도록 구성될 부분이니, 터미널 및 AI에게 연결을 요청하는 부분은 제거해주세요」 였고, 범위는 「그냥 전면 제거」 로 정하셨습니다. 그래서 대화창에서 여는 연결 창과 별도의 연결 페이지 양쪽에서 함께 지웠습니다 — 한쪽만 지우면 링크를 새 탭으로 여신 분은 옛 화면을 보시게 됩니다. 사라진 것은 「연결 준비」 버튼과 그것이 그리던 연결 정보·명령, 운영체제 탭과 명령 복사, AI 에게 「조사만 맡기기」·「전부 맡기기」 두 갈래 지시문, 그리고 「이 창을 닫으면 다시 볼 수 없습니다」 경고입니다 — 이제 화면에 그릴 연결 정보 자체가 없기 때문입니다. 연결에 필요한 정보는 여전히 발급되지만 프로그램에 곧바로 건네지므로 회원님이 그 값을 보시거나 복사하실 일이 없습니다. 실패했을 때 나오던 안내 세 종류도 「1단계 명령을 터미널에」 대신 연결 프로그램을 가리키게 고쳤습니다. 대가를 그대로 적습니다 — 앱이 없는 분께는 다른 길이 없고, 그것을 아시고 고르신 결정입니다. 그래서 받기 안내를 그 자리에 남겼습니다. 확인한 것: 지운 자리를 잠그고 있던 검사들을 지우지 않고 뒤집어 「이제 무엇이 참인가」 를 그대로 지키게 했고, 전체 회귀 검사가 통과했습니다. 아직 확인하지 못한 것: 이 화면 자체를 실제 윈도우 브라우저로 보는 일은 배포 뒤로 미뤘습니다.",
