          detail: "9월 3일과 9월 4일 안내에서 두 번 「이 프로그램을 이 서비스 화면에서 내려받는 자리가 아직 없다」 고 적어 드렸습니다. 이번에 그 자리를 만들었습니다 — 연결 화면에 「아직 DQA 앱이 없다면 — 받아서 실행하면 로그인과 연결을 그 창에서 끝낼 수 있습니다」 와 [DQA 앱 받기] 가 들어갑니다. 종전에 이 자리가 비어 있던 이유도 함께 적습니다: 설치 파일은 윈도우에서만 만들어지는데 저희 배포는 리눅스에서 돌아서, 화면이 바라보던 자리에는 파일이 영원히 놓이지 않았습니다. 이제 서버가 파일을 놓아 두는 별도의 자리를 보고, 실물이 실제로 있는지 크기와 지문까지 대조해 통과한 경우에만 이 안내를 냅니다 — 없는 내려받기를 권하면 회원님은 안내받은 대로 가셨다가 막히고, 그것을 스스로 우회하실 수 없기 때문입니다. 그래서 지금 이 자리는 보이지 않습니다: 첫 실제 설치 파일을 아직 올리지 않았습니다. 그때까지는 종전처럼 설치 파일을 따로 전달받으셔야 합니다. 이미 앱 창을 쓰고 계신 분께는 이 안내를 감춥니다 — 이미 설치하신 분께 받기를 권할 이유가 없습니다. 아직 확인하지 못한 것: 이 안내가 실제로 나타났다가 사라지는 전환을 브라우저로 본 적이 없습니다. 첫 실제 파일을 올릴 때 재겠습니다.",
